import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date) => void;
}

function startOfDay(date: Date): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

function addDays(date: Date, days: number): Date {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

function isSameDay(a: Date, b: Date): boolean {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [selectedDate, setSelectedDate] = useState<Date>(() => startOfDay(new Date()));

  const quickOptions = [
    { label: 'Сегодня', getDate: () => startOfDay(new Date()) },
    { label: 'Вчера', getDate: () => addDays(startOfDay(new Date()), -1) },
    { label: 'Неделя назад', getDate: () => addDays(startOfDay(new Date()), -7) },
  ];

  const handleDateChange = (date: Date | null) => {
    if (date) {
      const normalized = startOfDay(date);
      setSelectedDate(normalized);
      onChange?.(normalized);
    }
  };

  const handleQuickSelect = (date: Date) => {
    setSelectedDate(date);
    onChange?.(date);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
      <div style={{ display: 'flex', gap: 'var(--jx-r-sm)' }}>
        {quickOptions.map((option) => {
          const optionDate = option.getDate();
          return (
            <JxChip
              key={option.label}
              active={isSameDay(optionDate, selectedDate)}
              onClick={() => handleQuickSelect(optionDate)}
            >
              {option.label}
            </JxChip>
          );
        })}
      </div>
      <JxCalendar locale="ru-RU" value={selectedDate} onValueChange={handleDateChange} />
    </div>
  );
}

